const rows = $input.first().json.pendientes;
if (!Array.isArray(rows)) throw new Error('Se requiere el arreglo pendientes del radar');
const source = 'https://www.sercotec.cl/convocatoria/crece-multisectorial-provincia-de-iquique-region-de-tarapaca-2026/';
for (const row of rows) {
  if (row.expediente !== 'H&S' || row.fuente !== source ||
      !['ventas_uf', 'bases'].includes(row.requisito) ||
      typeof row.documento !== 'string') throw new Error('Pendiente inválido');
}
if (!rows.length) return [];
const body = rows.map(row => [
  '### ' + row.requisito,
  'Anterior: ' + JSON.stringify(row.anterior),
  'Actual: ' + JSON.stringify(row.actual),
  'Respaldo por revisar: ' + row.documento,
  'Fuente: ' + row.fuente
].join('\n')).join('\n\n');
return [{json:{title:'[Radar H&S] Crece Iquique · revisión de cambios',body}}];
